import { InvoiceLineGathererService } from './invoiceLineGatherer.service.js';

describe('repro gatherer', () => {
    it('ridge', async () => {
        const svc = new InvoiceLineGathererService();
        for (const key of ['catalogues/biz-ridge-2026-07.json', 'catalogues/biz-vale-2026-07.json']) {
            const res = await svc.gatherInvoiceLines({
                businessID: key.includes('ridge') ? 'biz-ridge' : 'biz-vale',
                catalogueBucket: 'metering-billing-sandbox',
                catalogueKey: key,
            });
            console.log('==== ' + key + ' ====');
            console.log(JSON.stringify(res, null, 2));
        }
        expect(true).toBe(true);
    }, 60000);
});
EOF
